import{_ as i,c as t,o as n,ag as a}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"A Community Guide to working with Aquisitions","description":"","frontmatter":{"title":"A Community Guide to working with Aquisitions"},"headers":[],"relativePath":"community/a-community-guide-to-working-with-aquisitions.md","filePath":"community/a-community-guide-to-working-with-aquisitions.md","lastUpdated":null}'),o={name:"community/a-community-guide-to-working-with-aquisitions.md"};function r(s,e,l,d,c,u){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="a-community-guide-to-working-with-aquisitions" tabindex="-1">A Community Guide to working with Aquisitions <a class="header-anchor" href="#a-community-guide-to-working-with-aquisitions" aria-label="Permalink to &quot;A Community Guide to working with Aquisitions&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The traditional U.S. military acquisition system can be slow, bureaucratic, and overly complex. This has led to significant inefficiencies in fielding necessary capabilities promptly. In contrast, conflict zones like Ukraine have demonstrated the effectiveness of an agile approach—rapidly deploying and refining technology based on real-time needs.</p><p>This guide is designed to help service members understand how they can influence the acquisition process, write better requirements, and push for necessary changes to streamline procurement and fielding efforts.</p><p>For training in this lane see [## Capability Gap, Risk Assessment, and Command Endorsement The current acquisition process leaves a critical gap between what our mission demands and the capabilities we currently field. This delta reduces operational effectiveness and poses significant risks to mission success and the safety of our personnel. Robust command endorsement at every echelon is essential to address this gap and drive rapid modernization.</p><h3 id="the-delta-between-mission-and-current-capabilities" tabindex="-1">The Delta Between Mission and Current Capabilities <a class="header-anchor" href="#the-delta-between-mission-and-current-capabilities" aria-label="Permalink to &quot;The Delta Between Mission and Current Capabilities&quot;">​</a></h3><ul><li><p><strong>Mission Requirements vs. Current Assets:</strong> Modern operations demand rapid decision-making, agile responses, and seamless technology integration. However, legacy systems and outdated processes fail to meet these evolving demands.</p></li><li><p><strong>Capability Gap:</strong> Delayed technology updates, inefficient integration, and reliance on outdated paradigms have created a significant gap between what the mission requires and what we currently field.</p></li></ul><h3 id="key-deficiencies" tabindex="-1">Key Deficiencies <a class="header-anchor" href="#key-deficiencies" aria-label="Permalink to &quot;Key Deficiencies&quot;">​</a></h3><ul><li><p><strong>Inadequate Agility:</strong> The traditional, waterfall acquisition model is too slow to respond to rapidly changing operational environments.</p></li><li><p><strong>Outdated Technologies:</strong> Legacy systems and outdated tools fail to address modern warfare challenges effectively.</p></li><li><p><strong>Fragmented Integration:</strong> Siloed efforts and non-interoperable systems hinder timely communication and coordinated responses.</p></li></ul><h3 id="specific-problem-statement" tabindex="-1">Specific Problem Statement <a class="header-anchor" href="#specific-problem-statement" aria-label="Permalink to &quot;Specific Problem Statement&quot;">​</a></h3><ul><li><p><strong>Operational Lag:</strong> The slow pace of modernizing legacy systems undermines our ability to respond swiftly in dynamic combat scenarios.</p></li><li><p><strong>Inefficient Integration:</strong> Fragmented systems and siloed efforts cause delays in sharing critical information and coordinating actions.</p></li><li><p><strong>Resource Misallocation:</strong> Continued investments in outdated technologies divert essential resources from developing and deploying next-generation capabilities.</p></li></ul><h3 id="impact-on-mission" tabindex="-1">Impact on Mission <a class="header-anchor" href="#impact-on-mission" aria-label="Permalink to &quot;Impact on Mission&quot;">​</a></h3><p>Failing to bridge this capability gap jeopardizes our operational objectives by:</p><ul><li><p><strong>Reducing Tactical Flexibility:</strong> Delays in acquiring and fielding new technologies limit our ability to adapt quickly on the battlefield.</p></li><li><p><strong>Compromising Situational Awareness:</strong> Inadequate or outdated systems can lead to poor decision-making and slower reaction times.</p></li><li><p><strong>Creating Strategic Vulnerabilities:</strong> Adversaries may exploit our technological lag, undermining overall mission success and national security.</p></li></ul><h3 id="risk-to-the-force" tabindex="-1">Risk to the Force <a class="header-anchor" href="#risk-to-the-force" aria-label="Permalink to &quot;Risk to the Force&quot;">​</a></h3><p>The current capability gap also places our service members at greater risk:</p><ul><li><p><strong>Increased Exposure to Threats:</strong> Outmoded equipment may not provide sufficient protection against modern, evolving threats.</p></li><li><p><strong>Lowered Morale:</strong> Persistent reliance on inadequate tools can erode confidence and reduce combat effectiveness.</p></li><li><p><strong>Misallocated Resources:</strong> Investing in outdated systems limits funding for innovative, life-saving technologies that could better protect our personnel.</p></li></ul><h3 id="command-endorsement-at-each-echelon" tabindex="-1">Command Endorsement at Each Echelon <a class="header-anchor" href="#command-endorsement-at-each-echelon" aria-label="Permalink to &quot;Command Endorsement at Each Echelon&quot;">​</a></h3><ul><li><p><strong>Unified Direction:</strong> Command endorsement at every level—strategic, operational, and tactical—is crucial to prioritize closing the capability gap.</p></li><li><p><strong>Empowerment and Accountability:</strong> Active backing from commanders empowers units to pursue rapid acquisition, testing, and deployment of innovative technologies, while establishing clear accountability.</p></li><li><p><strong>Accelerated Decision-Making:</strong> Strong command support streamlines approval processes, enabling faster resource mobilization and reducing bureaucratic delays.</p></li><li><p><strong>Feedback Integration:</strong> Command endorsement creates a structured feedback loop, ensuring that lessons learned from the field directly inform capability development and iterative improvements.</p></li></ul><p>Addressing this combined gap through targeted modernization and unified command support is essential to ensure our forces remain agile, well-equipped, and capable of meeting both current and future operational challenges.</p><h3 id="understanding-the-problem" tabindex="-1">Understanding the Problem <a class="header-anchor" href="#understanding-the-problem" aria-label="Permalink to &quot;Understanding the Problem&quot;">​</a></h3><p>The current acquisition process is dominated by:</p><ul><li><p><strong>Waterfall Planning</strong> – Long, inflexible cycles prioritizing predictability over adaptability.</p></li><li><p><strong>Unrealistic Requirements</strong> – Complex, contradictory requirements delay progress.</p></li><li><p><strong>Bureaucratic Bottlenecks</strong> – Lengthy approvals, redundant oversight, and outdated policies.</p></li><li><p><strong>Siloed Efforts</strong> – Lack of interoperability between systems and service branches.</p></li><li><p><strong>Institutional Resistance</strong> – A culture of risk aversion that discourages rapid iteration and innovation.</p></li></ul><p>If you are frustrated with these issues, the good news is that you can do something about it.</p><h3 id="what-you-can-do" tabindex="-1">What You Can Do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What You Can Do&quot;">​</a></h3><h3 id="_1-write-better-requirements" tabindex="-1"><strong>1. Write Better Requirements</strong> <a class="header-anchor" href="#_1-write-better-requirements" aria-label="Permalink to &quot;**1. Write Better Requirements**&quot;">​</a></h3><ul><li><p>Keep requirements <strong>simple, clear, and focused</strong> on solving a specific problem.</p></li><li><p>Avoid creating &quot;do-it-all&quot; systems that try to fulfill every need but end up being ineffective.</p></li><li><p>Use objective-based requirements instead of hard specifications.</p></li><li><p>Look at the <strong>USMC model</strong>—reducing a 200-requirement system to a two-page Statement of Need reduced development costs by <strong>40%</strong> and unit costs by <strong>25-30%</strong>.</p></li></ul><h3 id="_2-push-for-rapid-prototyping-and-field-testing" tabindex="-1"><strong>2. Push for Rapid Prototyping and Field Testing</strong> <a class="header-anchor" href="#_2-push-for-rapid-prototyping-and-field-testing" aria-label="Permalink to &quot;**2. Push for Rapid Prototyping and Field Testing**&quot;">​</a></h3><ul><li><p>Utilize <strong>Tactical Innovation and Combat Initiatives (TiC)</strong> to test solutions in the field.</p></li><li><p>Work with program offices to bypass bureaucratic delays.</p></li><li><p>Challenge outdated testing and evaluation requirements under <strong>DOT&amp;E oversight</strong>.</p></li></ul><h3 id="_3-demand-interoperability-standards" tabindex="-1"><strong>3. Demand Interoperability Standards</strong> <a class="header-anchor" href="#_3-demand-interoperability-standards" aria-label="Permalink to &quot;**3. Demand Interoperability Standards**&quot;">​</a></h3><ul><li><p>Advocate for <strong>plug-and-play architectures</strong> that prevent vendor lock-in.</p></li><li><p>Push for standardized software, cabling, and networking frameworks.</p></li><li><p>Reference standards such as:</p><ul><li><strong>MIL-STD-2525</strong> (military symbology and data structures)</li><li><strong>Joint sUAS CDD</strong> (requirements for joint UAS interoperability)</li></ul></li></ul><h3 id="_4-use-existing-rapid-acquisition-pathways" tabindex="-1"><strong>4. Use Existing Rapid Acquisition Pathways</strong> <a class="header-anchor" href="#_4-use-existing-rapid-acquisition-pathways" aria-label="Permalink to &quot;**4. Use Existing Rapid Acquisition Pathways**&quot;">​</a></h3><ul><li><p><strong>Joint Urgent Operational Need Statements (JUONS) &amp; Joint Emergent Operational Need Statements (JEONS)</strong> – Accelerate fielding for urgent requirements.</p></li><li><p><strong>SOCOM DIR 71-4</strong> – Provides a streamlined process for rapid prototyping.</p></li><li><p><strong>APFIT (Accelerated Procurement Funding for Innovative Technologies)</strong> – A funding stream for cutting-edge solutions.</p></li><li><p><strong>SORRD (Special Operations Rapid Requirements Development)</strong> – An alternative pathway for rapid fielding.</p></li></ul><h3 id="_5-engage-your-acquisition-personnel" tabindex="-1"><strong>5. Engage Your Acquisition Personnel</strong> <a class="header-anchor" href="#_5-engage-your-acquisition-personnel" aria-label="Permalink to &quot;**5. Engage Your Acquisition Personnel**&quot;">​</a></h3><ul><li><p>Find your <strong>TRADOC Capability Developer</strong>, <strong>Program Office POC</strong>, or <strong>G8/S8 representative</strong>.</p></li><li><p>Write and submit an <strong>Unfunded Requirement Justification</strong> for critical needs.</p></li><li><p>Use existing mechanisms such as <strong>SOF RAPTOR IV (SR-IV) IDIQ</strong> to fund innovative technologies.</p></li></ul><h3 id="_6-break-down-cultural-resistance" tabindex="-1"><strong>6. Break Down Cultural Resistance</strong> <a class="header-anchor" href="#_6-break-down-cultural-resistance" aria-label="Permalink to &quot;**6. Break Down Cultural Resistance**&quot;">​</a></h3><ul><li><p>Educate leadership on successful rapid acquisition models.</p></li><li><p>Push for an <strong>iterative development approach</strong> rather than waiting for &quot;perfect&quot; solutions.</p></li><li><p>Highlight past failures of rigid acquisitions (e.g., <strong>IVAS receiving $20B but still facing major usability issues</strong>).</p></li></ul><h3 id="questions-that-need-answers" tabindex="-1">Questions That Need Answers <a class="header-anchor" href="#questions-that-need-answers" aria-label="Permalink to &quot;Questions That Need Answers&quot;">​</a></h3><p>The following are key acquisition issues that remain unresolved:</p><ul><li><p>How can we consolidate <strong>Joint COP tools</strong> to eliminate redundant, non-communicating systems?</p></li><li><p>What is the best approach to <strong>accelerate DOT&amp;E oversight</strong> for rapid fielding?</p></li><li><p>How do we enforce interoperability <strong>across service branches</strong> to prevent silos?</p></li><li><p>What are specific examples of <strong>bad requirements</strong>, and how should they be fixed?</p></li></ul><h3 id="actionable-steps-for-every-service-member" tabindex="-1">Actionable Steps for Every Service Member <a class="header-anchor" href="#actionable-steps-for-every-service-member" aria-label="Permalink to &quot;Actionable Steps for Every Service Member&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>Action</th></tr></thead><tbody><tr><td>1. Find Your Acquisition POC</td><td>Identify who in your command is responsible for requirements and procurement</td></tr><tr><td>2. Write a Simple Requirement</td><td>Use the USMC model or SORRD format—avoid overcomplicated specifications</td></tr><tr><td>3. Push for Field Testing</td><td>Advocate for TiC initiatives and rapid prototyping under SOCOM DIR 71-4</td></tr><tr><td>4. Use Rapid Acquisition Pathways</td><td>Submit JUONS/JEONS, APFIT proposals, or utilize SORRD for rapid fielding</td></tr><tr><td>5. Enforce Interoperability</td><td>Ensure tech aligns with Joint sUAS CDD, MIL-STD-2525, and gov-owned architectures</td></tr><tr><td>6. Educate Your Leadership</td><td>Present successful case studies (e.g., Marine Corps rapid acquisition model)</td></tr></tbody></table><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>The acquisition process can be slow and frustrating, but real change is possible when <strong>capability developers, warfighters, and leadership</strong> work together. By writing clear, focused requirements, pushing for rapid prototyping, and leveraging existing rapid acquisition channels, service members can <strong>cut through bureaucracy</strong> and <strong>ensure our forces get the capabilities they need—when they need them</strong>.</p><p>If every service member reading this guide takes just one step on Monday—whether it’s finding their acquisition contact, submitting an unfunded requirement, or challenging outdated processes—we will move the needle toward a <strong>more agile, responsive, and effective military acquisition system</strong>.</p><p>](/learning-defense-acquisition-university-dau)</p>',46)])])}const h=i(o,[["render",r]]);export{g as __pageData,h as default};
